changeSet.sql:
ALTER TABLE reaction
ADD CONSTRAINT chk_reaction_response_shape CHECK (
    usefulness IS NOT NULL OR action IS NOT NULL OR explanation IS NULL
);

ALTER TABLE practice_area RENAME TO practice_group;
ALTER TABLE practice RENAME COLUMN practice_area_id TO practice_group_id;
ALTER TABLE practice_revision RENAME COLUMN area_slug TO group_slug;
ALTER TABLE practice_revision RENAME COLUMN area_name TO group_name;
ALTER TABLE practice_revision RENAME COLUMN area_description TO group_description;
ALTER TABLE practice_revision RENAME COLUMN area_icon TO group_icon;
ALTER TABLE practice_revision RENAME COLUMN area_color TO group_color;
ALTER TABLE curated_practice_override RENAME COLUMN area_slug TO group_slug;
ALTER TABLE curated_area_override RENAME TO curated_group_override;

ALTER TABLE practice_group RENAME CONSTRAINT uk_practice_area_workspace_slug TO uk_practice_group_workspace_slug;
ALTER TABLE practice_group RENAME CONSTRAINT fk_practice_area_workspace TO fk_practice_group_workspace;
ALTER TABLE practice_group RENAME CONSTRAINT "practice_areaPK" TO "practice_groupPK";
ALTER TABLE practice_group RENAME CONSTRAINT ck_practice_area_curated_origin TO ck_practice_group_curated_origin;
ALTER TABLE practice_group RENAME CONSTRAINT ck_practice_area_curated_fingerprint TO ck_practice_group_curated_fingerprint;
ALTER TABLE practice_group RENAME CONSTRAINT chk_practice_area_autonomy TO chk_practice_group_autonomy;
ALTER TABLE practice RENAME CONSTRAINT fk_practice_area TO fk_practice_group;
ALTER TABLE curated_group_override RENAME CONSTRAINT ck_curated_area_override_says_something TO ck_curated_group_override_says_something;
ALTER TABLE curated_group_override RENAME CONSTRAINT ck_curated_area_override_shape TO ck_curated_group_override_shape;
ALTER TABLE curated_group_override RENAME CONSTRAINT ck_curated_area_override_position TO ck_curated_group_override_position;
ALTER TABLE curated_group_override RENAME CONSTRAINT ck_curated_area_override_based_on TO ck_curated_group_override_based_on;
ALTER INDEX idx_practice_practice_area RENAME TO idx_practice_practice_group;
ALTER INDEX idx_practice_area_order RENAME TO idx_practice_group_order;
ALTER INDEX idx_practice_area_workspace_dashboard_visibility RENAME TO idx_practice_group_workspace_dashboard_visibility;
ALTER INDEX idx_practice_area_source_curated_slug RENAME TO idx_practice_group_source_curated_slug;

ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type
    CHECK (entity_type IN (
        'PRACTICE_REVIEW_SETTINGS', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING',
        'WORKSPACE_ROLE', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS',
        'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_ACTIVE', 'PRACTICE_USAGE',
        'PRACTICE_DEFINITION', 'PRACTICE_GROUP', 'PRACTICE_AREA', 'CURATED_PRACTICE',
        'CURATED_PRACTICE_GROUP', 'CURATED_PRACTICE_AREA',
        'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET',
        'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET', 'REVIEW_BACKFILL_RUN',
        'REVIEW_SWEEP_SCHEDULE', 'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'
    ));

DO $functions$
DECLARE definition text;
BEGIN
    SELECT pg_get_functiondef('enforce_practice_revision_immutability()'::regprocedure)
      INTO definition;
    definition := replace(definition, 'area_slug', 'group_slug');
    definition := replace(definition, 'area_name', 'group_name');
    definition := replace(definition, 'area_description', 'group_description');
    definition := replace(definition, 'area_icon', 'group_icon');
    definition := replace(definition, 'area_color', 'group_color');
    definition := replace(definition, 'practice_area_id', 'practice_group_id');
    definition := replace(definition, 'practice_area area', 'practice_group practice_group');
    definition := replace(definition, 'area.slug', 'practice_group.slug');
    EXECUTE definition;
    SELECT pg_get_functiondef('enforce_practice_current_revision_projection()'::regprocedure)
      INTO definition;
    definition := replace(definition, 'area_slug', 'group_slug');
    definition := replace(definition, 'area_name', 'group_name');
    definition := replace(definition, 'area_description', 'group_description');
    definition := replace(definition, 'area_icon', 'group_icon');
    definition := replace(definition, 'area_color', 'group_color');
    definition := replace(definition, 'practice_area_id', 'practice_group_id');
    definition := replace(definition, 'practice_area area', 'practice_group practice_group');
    definition := replace(definition, 'area.slug', 'practice_group.slug');
    EXECUTE definition;
END
$functions$;

